```javascript
const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let idx = 0;
const L = parseInt(data[idx++], 10);
const C = parseInt(data[idx++], 10);
const E = L + C;
const V = 676;
const coeff = Array.from({ length: E }, () => new Uint8Array(V));
const present = new Array(V).fill(false);
const target = new Array(E);

for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    const name = data[idx++];
    const v = (name.charCodeAt(0) - 97) * 26 + (name.charCodeAt(1) - 97);
    present[v] = true;
    coeff[r][v]++;
    coeff[L + c][v]++;
  }
  target[r] = BigInt(data[idx++]);
}

for (let c = 0; c < C; c++) {
  target[L + c] = BigInt(data[idx++]);
}

const unknownCount = new Array(E);
for (let e = 0; e < E; e++) {
  let cnt = 0;
  const row = coeff[e];
  for (let v = 0; v < V; v++) {
    if (row[v] > 0) cnt++;
  }
  unknownCount[e] = cnt;
}

const known = new Array(V).fill(false);
const value = new Array(V).fill(0n);
const knownSum = new Array(E).fill(0n);
let solved = 0;
let totalVars = 0;
for (let v = 0; v < V; v++) if (present[v]) totalVars++;

while (solved < totalVars) {
  let e = -1;
  for (let i = 0; i < E; i++) {
    if (unknownCount[i] === 1) {
      e = i;
      break;
    }
  }
  if (e === -1) break;

  let v = -1;
  const row = coeff[e];
  for (let i = 0; i < V; i++) {
    if (row[i] > 0 && !known[i]) {
      v = i;
      break;
    }
  }

  const coeffVal = BigInt(row[v]);
  const val = (target[e] - knownSum[e]) / coeffVal;
  value[v] = val;
  known[v] = true;
  solved++;

  for (let f = 0; f < E; f++) {
    const c = coeff[f][v];
    if (c > 0) {
      knownSum[f] += BigInt(c) * val;
      unknownCount[f]--;
    }
  }
}

const out = [];
for (let v = 0; v < V; v++) {
  if (present[v]) {
    const name = String.fromCharCode(97 + Math.floor(v / 26)) + String.fromCharCode(97 + (v % 26));
    out.push(name + ' ' + value[v].toString());
  }
}
console.log(out.join('\n'));
